#include <array>
#include <cstddef>
#include <cstring>
#include <iostream>
#include <type_traits>

int main()
{
    int count{42};
    static_assert(std::is_trivially_copyable_v<int>);
    std::array<std::byte, sizeof(count)> saved{};
    std::memcpy(saved.data(), &count, sizeof(count));
    count = 9;
    std::memcpy(&count, saved.data(), sizeof(count));
    std::cout << count << '\n';
}
